const marketingLogo='<span class="campaign-logo">pracuj<span>.be</span></span>';
function materialsScreen(){return `${nav()}<main class="materials"><header class="materials-heading"><span class="eyebrow">PRACUJ.BE / SYSTEM KOMUNIKACJI</span><h1>Jedna marka.<br>W każdym miejscu.</h1><p>Biel daje przestrzeń. Czerwień wskazuje następny krok. Paszport pracy porządkuje informacje.</p><div class="material-links"><a href="#mail-design">Newsletter</a><a href="#ad-design">Reklamy</a><a href="#social-design">Social media</a><a href="#system-design">Zasady</a></div></header><section id="mail-design"><div class="section-head"><div><span class="eyebrow">01 / E-MAIL</span><h2>Praca w Twojej skrzynce.</h2><p>Newsletter ofertowy, szerokość 600 px.</p></div><a class="btn secondary" href="materials/newsletter.html" target="_blank">Otwórz szablon HTML ↗</a></div><div class="mail-stage"><aside><span class="eyebrow">TEMAT WIADOMOŚCI</span><h3>Nowe oferty. Twój kolejny krok.</h3><p>Preheader: Sprawdź stanowiska, miejsca i warunki pracy w Belgii.</p><hr><h3>Rytm wiadomości</h3><p>Krótki wstęp, trzy oferty, jedna główna akcja. Na końcu ustawienia powiadomień i wypisanie.</p><span class="material-note">Dane i firmy w materiałach są przykładowe.</span></aside><iframe title="Projekt newsletteru Pracuj.be" src="materials/newsletter.html"></iframe></div></section><section id="ad-design"><div class="section-head"><div><span class="eyebrow">02 / KAMPANIA DISPLAY</span><h2>Mało miejsca. Jasny przekaz.</h2></div></div><div class="ad-wide"><img src="materials/banner-1200x300.svg" alt="Baner: Twoje umiejętności. Nowe możliwości. Praca w Belgii bez CV."><a href="materials/banner-1200x300.svg" download>Pobierz SVG · 1200 × 300</a></div><div class="ad-grid"><article><img src="materials/banner-300x250.svg" alt="Reklama dla kandydatów: Praca w Belgii. Po Twojemu."><a href="materials/banner-300x250.svg" download>Pobierz SVG · 300 × 250</a></article><article><img src="materials/banner-300x600.svg" alt="Reklama dla firm: Twój zespół zaczyna się od człowieka."><a href="materials/banner-300x600.svg" download>Pobierz SVG · 300 × 600</a></article><aside class="campaign-notes"><h3>Dwa głosy tej samej marki.</h3><p><strong>Dla kandydata</strong><br>Umiejętności, miejsce, warunki. Prosty profil zamiast CV.</p><p><strong>Dla pracodawcy</strong><br>Konkretne stanowisko i ludzie, którzy potrafią je wykonywać.</p><p>Każdy baner ma jeden cel i jeden przycisk. Bez niepotwierdzonych liczb i obietnic zatrudnienia.</p></aside></div></section><section id="social-design"><div class="section-head"><div><span class="eyebrow">03 / SOCIAL MEDIA</span><h2>Oferty, które mają swój format.</h2></div></div><div class="social-grid"><article><img src="materials/social-1080.svg" alt="Kwadratowy paszport oferty operatora wózka widłowego"><a href="materials/social-1080.svg" download>Pobierz SVG · post 1080 × 1080</a></article><article><img src="materials/story-1080x1920.svg" alt="Relacja Pracuj.be: Pokaż, co potrafisz. Profil zamiast CV."><a href="materials/story-1080x1920.svg" download>Pobierz SVG · relacja 1080 × 1920</a></article></div></section><section id="system-design"><span class="eyebrow">04 / MAŁE ELEMENTY, WSPÓLNY CHARAKTER</span><h2>System, który można rozwijać.</h2><div class="identity-grid"><article><h3>Podpis e-mail</h3>${marketingLogo}<p><strong>Zespół Pracuj.be</strong><br>Praca w Belgii, po prostu.</p><small>Imię, rola i kontakt w wersji produkcyjnej.</small></article><article><h3>Potwierdzenie aplikacji</h3><span class="status good">Zgłoszenie wysłane</span><p>Twój profil trafił do pracodawcy. Status sprawdzisz w swoich aplikacjach.</p><small>Przykład wiadomości transakcyjnej.</small></article><article><h3>Wariant bez stawki</h3><p>Usuwamy pole wynagrodzenia. Miejsce i warunki wypełniają przestrzeń. Nie zastępujemy braku danych obietnicą.</p></article></div><div class="brand-rules"><p><strong>Logo</strong> · czarne „pracuj”, białe „.be” w czerwonym kafelku. Pole ochronne: wysokość litery „b”.</p><p><strong>Kolor</strong> · biel #FFFFFF, czerwień #D92932, czerń #151515. Szarość wyłącznie jako tło pomocnicze.</p><p><strong>Typografia</strong> · DM Sans w serwisie; Arial jako bezpieczny krój w e-mailach i przenośnych materiałach.</p><p><strong>Forma</strong> · zaokrąglone pola, cienkie linie, duże wartości i dyskretne etykiety. Motyw paszportu zamiast przypadkowych dekoracji.</p></div><p class="material-note">Pliki SVG są edytowalnymi projektami. Przed emisją należy zastąpić dane demonstracyjne, ustawić docelowe adresy i wyeksportować format wymagany przez wybraną sieć reklamową.</p></section></main>${footer()}`;}
extraScreens.materials=materialsScreen;
